}

/** The claims that count in a period's due-totals among these: those whose status at the end of the day given (see
 *  statusAt) is OPEN, PENDING or SETTLED, left out as live leaves them out on the sheet's today (yyyy-mm-dd):
 *  deferred, or left out by their person (among the people given; see leftOut). */
export function countedAt(claims: Claim[], people: Person[], day: string, today: string): Claim[] {
  const byId = new Map(people.map((p) => [p.id, p]));
  return claims.filter((c) => {
    const at = statusAt(c, day);
    return (at === 'OPEN' || at === 'PENDING' || at === 'SETTLED') && !c.deferred && !leftOut(c, byId, today);
  });
}

/** A claim's due-by (yyyy-mm-dd), as the server works it out in business days. */
export function dueBy(claim: Claim): string {
  return claim.dueBy;
}

/** The day (yyyy-mm-dd) a claim's late charge counts from: its due-by plus its grace (days; see Late). */
export function lateFrom(claim: Claim, grace = 0): string {
  if (grace === 0) return dueBy(claim);
  return new Date(Date.parse(`${dueBy(claim)}T00:00:00Z`) + grace * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
}

/** Whether a claim is overdue: it is OPEN or PENDING, not deferred, and its due-by plus its grace (days) is before
 *  the sheet's today. */
export function overdue(claim: Claim, today: string, grace = 0): boolean {
  return unsettled(claim) && !claim.deferred && today !== '' && lateFrom(claim, grace) < today;
}

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
  });
}

/** Every tag ever used on the sheet's claims, sorted (kept even once no claim carries it). Under the claims' key, so
 *  it is fetched again whenever they are. */
export function useTagsUsed(sheetId: string) {
  return useQuery({
    queryKey: [...claimsKey(sheetId), 'tags'] as const,
    queryFn: () => getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/tags`),
  });
}

/** The number of the sheet's last settle batch (null when there has been none): each bulk settle that settled at
 *  least one claim (one left PENDING counts) is the next, numbered 1, 2, ... on the sheet. */
export function useLastBatch(sheetId: string) {
  return useQuery({
    queryKey: [...claimsKey(sheetId), 'settle-batch'] as const,
    queryFn: () => getJson<{ last: number | null }>(`/api/sheets/${encodeURIComponent(sheetId)}/settle-batch`),
  });
}

/** The id of the claim whose editor is open ('' when each person's claim form adds a new claim). */
export function useEditingClaim() {
  return useSearchParam('editClaim', asString);
}

/** The amounts of the claims that count (OPEN, PENDING and SETTLED) added up exactly (in cents) and shown
 *  with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((total, c) => total + Math.round(Number(c.amount) * 100), 0);
  const abs = Math.abs(cents);
  return `${cents < 0 ? '-' : ''}${Math.floor(abs / 100)}.${String(abs % 100).padStart(2, '0')}`;
}
import { useQuery } from '@tanstack/react-query';
import { useNavigate } from '@tanstack/react-router';
import { getJson } from '../../api/http';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

/** A person on a sheet: a name and a grade (A, B or C: the one in force on the sheet's today), the version stored (one more on each edit), how many
 *  statements have been taken of them, and the last one's due-total (null when n/a, or none taken) and date
 *  (the sheet's today then; null when none taken), the date they are retired from (null: not retired), whether
 *  they have any hold, their dated grades, earliest first, and their holds in the order they were put on (their OPEN
 *  claims dated within one, not bound by a statement, count in no live total), their own terms in days (null: none), and their contact (trimmed, lower-cased; null: none). */
export type Person = { id: number; name: string; grade: string; version: number; statementCount: number;
  statedTotal: string | null; statementDate: string | null; retiredFrom: string | null; held: boolean;
  grades: Grade[]; holds: Hold[]; terms: number | null;
  contact: string | null };

/** A hold on a person, from its from-date to its to-date, both included (yyyy-mm-dd, or null: unbounded on that side). */
export type Hold = { from: string | null; to: string | null };

/** Whether one of the person's holds covers the date (yyyy-mm-dd). */
export function heldOn(person: Person | undefined, date: string): boolean {
  return (person?.holds ?? []).some((h) => (h.from === null || h.from <= date) && (h.to === null || date <= h.to));
}

/** Whether the person's retirement date is reached on the sheet's today (yyyy-mm-dd; '' while loading: not reached):
 *  from then their OPEN and PENDING claims not bound by a statement count in no live total. */
export function retiredOn(person: Person | undefined, today: string): boolean {
  return today !== '' && person?.retiredFrom != null && person.retiredFrom <= today;
}

/** A grade a person was given, in force from its from-date (yyyy-mm-dd, or null: from the beginning of time). */
export type Grade = { grade: string; from: string | null };

/** The person's grade in force on a date (yyyy-mm-dd): the one whose from-date is the latest on or before it,
 *  a grade with no from-date applying from the beginning of time; '' when none applies. */
export function gradeOn(person: Person | undefined, date: string): string {
  let found: Grade | undefined;
  for (const g of person?.grades ?? []) {
    if (g.from !== null && g.from > date) continue;
    if (!found || (found.from ?? '') <= (g.from ?? '')) found = g;
  }
  return found?.grade ?? '';
}

export const GRADES = ['A', 'B', 'C'] as const;

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery({
    queryKey: peopleKey(sheetId),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
  });
}

/** The id of the person whose editor is open ('' when the form adds a new person). */
export function useEditingPerson() {
  return useSearchParam('editPerson', asString);
}

/** Close the person's editor, when it is still theirs that is open (another may have been opened since). */
export function useCloseEditor() {
  const navigate = useNavigate();
  return (personId: number) =>
    void navigate({
      to: '.',
      search: (prev: Record<string, unknown>) => {
        if (prev.editPerson !== String(personId)) return prev;
        const next = { ...prev };
        delete next.editPerson;
        return next;
      },
      replace: true,
    });
}

/** Whether retired people are listed: off when the screen is first opened, and left as it is by loading a sheet. */
export function useShowRetired() {
  return useSearchParam('showRetired', asFlag);
}

